python3 -c "
import json, sys

with open('/work/output/artifacts/skill-flow-move-node/BellevueWeather/BellevueWeather/BellevueWeather.flow') as f:
    flow = json.load(f)

nodes = {n['id']: n for n in flow['nodes']}
edges = flow['edges']

print('=== NODES ===')
for nid, n in nodes.items():
    print(f'  {nid}: {n[\"type\"]}')

print()
print('=== EDGES ===')
for e in edges:
    print(f'  {e[\"sourceNodeId\"]}:{e[\"sourcePort\"]} -> {e[\"targetNodeId\"]}:{e[\"targetPort\"]}')

print()
print('=== VALIDATION ===')
errors = []

# Check all edge node references exist
for e in edges:
    if e['sourceNodeId'] not in nodes:
        errors.append(f'Edge {e[\"id\"]}: unknown sourceNodeId {e[\"sourceNodeId\"]}')
    if e['targetNodeId'] not in nodes:
        errors.append(f'Edge {e[\"id\"]}: unknown targetNodeId {e[\"targetNodeId\"]}')

# Check decision node has both true and false outgoing edges
decision_edges = [e for e in edges if e['sourceNodeId'] == 'checkTemperature']
ports = {e['sourcePort'] for e in decision_edges}
if 'true' not in ports:
    errors.append('checkTemperature missing true branch')
if 'false' not in ports:
    errors.append('checkTemperature missing false branch')

# Both branches should go to formatSummary
for e in decision_edges:
    if e['targetNodeId'] != 'formatSummary':
        errors.append(f'checkTemperature branch {e[\"sourcePort\"]} does not go to formatSummary, goes to {e[\"targetNodeId\"]}')

# formatSummary should go to end
fs_out = [e for e in edges if e['sourceNodeId'] == 'formatSummary']
if len(fs_out) != 1 or fs_out[0]['targetNodeId'] != 'end':
    errors.append('formatSummary does not connect to single end node')

# Check decision expression references getWeather
ct = nodes['checkTemperature']
expr = ct['inputs']['expression']
if 'getWeather' not in expr:
    errors.append(f'checkTemperature expression does not reference getWeather: {expr}')
else:
    print(f'  checkTemperature expression: {expr}')

# Check formatSummary script references checkTemperature.matchedCaseId
fs = nodes['formatSummary']
script = fs['inputs']['script']
if 'checkTemperature.matchedCaseId' not in script:
    errors.append('formatSummary script does not reference checkTemperature.matchedCaseId')
else:
    print('  formatSummary script uses checkTemperature.matchedCaseId: OK')

if 'nice day' in script and 'bring a jacket' in script:
    print('  formatSummary picks correct messages: OK')
else:
    errors.append('formatSummary does not contain expected messages')

# Check single end node
end_nodes = [n for n in nodes.values() if n['type'] == 'core.control.end']
print(f'  End nodes: {[n[\"id\"] for n in end_nodes]}')
if len(end_nodes) != 1:
    errors.append(f'Expected 1 end node, found {len(end_nodes)}')

if errors:
    print()
    print('ERRORS:')
    for err in errors:
        print(f'  ERROR: {err}')
    sys.exit(1)
else:
    print()
    print('All checks passed.')
"

